mapper.select:
SELECT
    #{date} AS dtStats,
    COUNT(*) AS inCnt,
    IFNULL(SUM(CASE WHEN RESULT IN ('0', '1000') THEN 1 ELSE 0 END), 0) AS succCnt,
    IFNULL(SUM(CASE WHEN RESULT IN ('9999', '-1') THEN 1 ELSE 0 END), 0) AS errorCnt,
    IFNULL(SUM(CASE WHEN RESULT NOT IN ('0', '1000', '9999', '-1', '') AND RESULT IS NOT NULL THEN 1 ELSE 0 END), 0) AS failCnt,
    0 AS ingCnt,
    0 AS waitCnt
FROM ${tableName}

    DATE(SAVE_TIME) = #{date}

        AND EXT_COL3 = #{userId}


        AND EXT_COL3 IN

            #{uid}



        AND MSG_TYPE = #{msgType}




                AND (EXT_COL0 IS NULL OR EXT_COL0 = 0)


                AND EXT_COL0 IS NOT NULL AND EXT_COL0 != 0

SELECT COUNT(*)
FROM msg_queue

    STAT = '0'
    AND DATE(REQUEST_TIME) = #{date}
    AND REQUEST_TIME > NOW()

        AND EXT_COL3 = #{userId}


        AND EXT_COL3 IN

            #{uid}



        AND MSG_TYPE = #{msgType}




                AND (EXT_COL0 IS NULL OR EXT_COL0 = 0)


                AND EXT_COL0 IS NOT NULL AND EXT_COL0 != 0

SELECT COUNT(*)
FROM msg_queue

    STAT IN ('1', '2')
    AND DATE(REQUEST_TIME) = #{date}
    AND REQUEST_TIME <= NOW()

        AND EXT_COL3 = #{userId}


        AND EXT_COL3 IN

            #{uid}



        AND MSG_TYPE = #{msgType}




                AND (EXT_COL0 IS NULL OR EXT_COL0 = 0)


                AND EXT_COL0 IS NOT NULL AND EXT_COL0 != 0
